### Skill 3: 单元测试生成 Skill

```typescript
// skills/gen-unit-tests.ts

interface TestConfig {
  filePath: string              // 源文件路径
  testFramework: 'vitest' | 'jest'
  includeE2E?: boolean
  mockExternal?: boolean
}

class GenUnitTestsSkill {
  async execute(config: TestConfig) {
    // 读取源文件
    const sourceCode = await fs.readFile(config.filePath, 'utf-8')

    // 分析源代码的函数和逻辑
    const analysis = await this.analyzeCode(sourceCode)

    // 生成测试
    const prompt = `
    为以下代码生成完整的单元测试：

    【源代码】
    \`\`\`
    ${sourceCode}
    \`\`\`

    【分析结果】
    - 导出函数：${analysis.exportedFunctions.join(', ')}
    - 内部逻辑：${analysis.logicDescription}
    - 边界条件：${analysis.edgeCases.join(', ')}

    【测试要求】
    1. 使用 ${config.testFramework}
    2. 覆盖所有导出函数
    3. 覆盖边界条件：${config.mockExternal ? '使用 Mock' : '不使用 Mock'}
    4. 每个 test 应该是独立的
    5. 包含正常情况、边界情况、异常情况

    输出完整的测试代码。
    `

    const tests = await claude.messages.create({
      model: 'claude-opus',
      max_tokens: 4000,
      messages: [{ role: 'user', content: prompt }]
    })

    return this.extractCode(tests.content[0].text, 'typescript')
  }

  private async analyzeCode(code: string) {
    // 使用 AST 解析或 Claude 分析代码
    // 返回关键信息
    return {
      exportedFunctions: [],
      logicDescription: '',
      edgeCases: []
    }
  }
}
```

