### Skill 5: API 模型生成 Skill

```typescript
// skills/gen-api-models.ts

interface ApiSpecConfig {
  apiDoc: string  // OpenAPI/Swagger 文档或 API 描述
  outputFormat: 'typescript' | 'zod'
  includeServices?: boolean
}

class GenApiModelsSkill {
  async execute(config: ApiSpecConfig) {
    const prompt = `
    基于以下 API 文档，生成对应的 TypeScript 类型和服务：

    【API 文档】
    ${config.apiDoc}

    【需要生成】
    1. TypeScript 接口定义（request/response types）
    2. ${config.outputFormat === 'zod' ? 'Zod 验证 schema' : '完整的类型定义'}
    3. ${config.includeServices ? 'API 服务类（包含请求方法）' : ''}
    4. Mock 数据（用于测试）

    【代码规范】
    - 使用 TypeScript 4.5+
    - 包含详细的注释说明
    - 所有 API 字段都要有说明
    - 区分 required 和 optional 字段
    `

    const models = await claude.messages.create({
      model: 'claude-opus',
      max_tokens: 3000,
      messages: [{ role: 'user', content: prompt }]
    })

    return this.extractCode(models.content[0].text, 'typescript')
  }
}
```

