## Agent 完整实现示例

### Agent 1: 研发效率 Agent（完整代码）

```typescript
// agents/research-development-agent.ts

import { Claude } from '@anthropic-ai/sdk'
import { GenVueComponentSkill } from '../skills/gen-vue-component'
import { GenReactComponentSkill } from '../skills/gen-react-component'
import { GenUnitTestsSkill } from '../skills/gen-unit-tests'
import { GenApiModelsSkill } from '../skills/gen-api-models'

interface FeatureRequirement {
  title: string
  description: string
  framework: 'vue' | 'react'
  scope: 'page' | 'component' | 'feature'
  apiRequirements?: string
  outputDir: string
}

class ResearchDevelopmentAgent {
  private claude = new Claude()
  private skills = {
    genVueComponent: new GenVueComponentSkill(),
    genReactComponent: new GenReactComponentSkill(),
    genUnitTests: new GenUnitTestsSkill(),
    genApiModels: new GenApiModelsSkill()
  }

  async execute(requirement: FeatureRequirement) {
    console.log(`\n🚀 开始处理需求: ${requirement.title}`)

    // 第1步：需求理解和分解
    console.log('📋 第1步：理解和分解需求...')
    const analysis = await this.analyzeRequirement(requirement)

    // 第2步：生成 API 模型（如需要）
    let apiModels = ''
    if (requirement.apiRequirements) {
      console.log('🔌 第2步：生成 API 模型...')
      apiModels = await this.skills.genApiModels.execute({
        apiDoc: requirement.apiRequirements,
        outputFormat: 'typescript',
        includeServices: true
      })
      await this.saveFile(`${requirement.outputDir}/types/api.ts`, apiModels)
      console.log('✅ API 模型已生成')
    }

    // 第3步：生成组件/页面代码
    console.log('🎨 第3步：生成代码...')
    const componentCode = await this.generateComponentCode(requirement, analysis)
    await this.saveFile(`${requirement.outputDir}/${analysis.componentName}.vue`, componentCode.component)
    console.log('✅ 组件代码已生成')

    // 第4步：生成单元测试
    console.log('🧪 第4步：生成单元测试...')
    const testCode = await this.skills.genUnitTests.execute({
      filePath: `${requirement.outputDir}/${analysis.componentName}.vue`,
      testFramework: 'vitest'
    })
    await this.saveFile(`${requirement.outputDir}/${analysis.componentName}.test.ts`, testCode)
    console.log('✅ 测试代码已生成')

    // 第5步：生成类型定义
    console.log('📝 第5步：生成类型定义...')
    const typeCode = componentCode.types
    await this.saveFile(`${requirement.outputDir}/types/${analysis.componentName}.ts`, typeCode)
    console.log('✅ 类型定义已生成')

    // 第6步：生成文档
    console.log('📚 第6步：生成文档...')
    const docCode = componentCode.doc
    await this.saveFile(`${requirement.outputDir}/${analysis.componentName}.md`, docCode)
    console.log('✅ 文档已生成')

    // 第7步：验证
    console.log('✔️  第7步：验证生成的代码...')
    const validation = await this.validateGeneratedCode(componentCode, testCode)

    console.log(`\n✨ 需求处理完成！`)
    console.log('📦 生成的文件:')
    console.log(`  - ${analysis.componentName}.vue`)
    console.log(`  - ${analysis.componentName}.test.ts`)
    console.log(`  - types/${analysis.componentName}.ts`)
    console.log(`  - ${analysis.componentName}.md`)
    if (apiModels) console.log(`  - types/api.ts`)

    return {
      componentCode,
      testCode,
      typeCode,
      docCode,
      apiModels,
      validation
    }
  }

  private async analyzeRequirement(requirement: FeatureRequirement) {
    const prompt = `
    分析这个功能需求，给出实现计划：

    【需求】
    标题：${requirement.title}
    描述：${requirement.description}
    框架：${requirement.framework}

    【需要分析】
    1. 核心功能有哪些？
    2. 需要哪些字段和状态？
    3. 需要哪些用户交互？
    4. 需要调用哪些 API？

    【输出格式】
    用 JSON 格式返回：
    {
      "componentName": "XxxComponent",
      "features": ["feature1", "feature2"],
      "states": ["state1", "state2"],
      "interactions": ["interaction1"],
      "apis": ["api1", "api2"],
      "dependencies": []
    }
    `

    const analysis = await this.claude.messages.create({
      model: 'claude-opus',
      max_tokens: 1000,
      messages: [{ role: 'user', content: prompt }]
    })

    try {
      const jsonMatch = analysis.content[0].text.match(/\{[\s\S]*\}/)
      return JSON.parse(jsonMatch![0])
    } catch {
      return {
        componentName: requirement.title.replace(/\s+/g, ''),
        features: [],
        states: [],
        interactions: [],
        apis: [],
        dependencies: []
      }
    }
  }

  private async generateComponentCode(
    requirement: FeatureRequirement,
    analysis: any
  ) {
    if (requirement.framework === 'vue') {
      return await this.skills.genVueComponent.execute({
        name: analysis.componentName,
        type: requirement.scope === 'page' ? 'table' : 'card',
        styling: 'tailwind',
        features: analysis.features
      })
    } else {
      return await this.skills.genReactComponent.execute({
        name: analysis.componentName,
        type: 'functional',
        hooks: ['useState', 'useEffect'],
        styling: 'tailwind',
        typescript: true
      })
    }
  }

  private async validateGeneratedCode(componentCode: any, testCode: string) {
    // 验证生成的代码是否有语法错误等
    return {
      valid: true,
      issues: []
    }
  }

  private async saveFile(path: string, content: string) {
    const fs = await import('fs').then(m => m.promises)
    const dir = require('path').dirname(path)
    await fs.mkdir(dir, { recursive: true })
    await fs.writeFile(path, content)
  }
}

// 使用示例
const agent = new ResearchDevelopmentAgent()
await agent.execute({
  title: '用户管理页面',
  description: '创建一个用户列表和编辑页面，包括增删改查功能',
  framework: 'vue',
  scope: 'page',
  apiRequirements: `
    GET /api/users - 获取用户列表
    GET /api/users/:id - 获取用户详情
    POST /api/users - 创建用户
    PUT /api/users/:id - 更新用户
    DELETE /api/users/:id - 删除用户
  `,
  outputDir: './src/pages/users'
})
```

