### Agent 2: Code Review Agent (GitHub Actions)

```yaml
# .github/workflows/ai-code-review.yml

name: AI Code Review Agent

on:
  pull_request:
    types: [opened, synchronize]

jobs:
  review:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v3

      - name: Set up Node
        uses: actions/setup-node@v3
        with:
          node-version: '18'

      - name: Install dependencies
        run: npm ci

      - name: Run AI Code Review
        env:
          ANTHROPIC_API_KEY: ${{ secrets.ANTHROPIC_API_KEY }}
          GITHUB_TOKEN: ${{ secrets.GITHUB_TOKEN }}
        run: |
          node scripts/ai-code-review-agent.js \
            --pr ${{ github.event.pull_request.number }} \
            --owner ${{ github.repository_owner }} \
            --repo ${{ github.event.repository.name }}
```

```typescript
// scripts/ai-code-review-agent.ts

import { Octokit } from '@octokit/rest'
import { Claude } from '@anthropic-ai/sdk'
import { CodeReviewSkill } from '../skills/code-review'

class CodeReviewAgent {
  private octokit = new Octokit({ auth: process.env.GITHUB_TOKEN })
  private claude = new Claude()
  private reviewSkill = new CodeReviewSkill()

  async reviewPR(owner: string, repo: string, prNumber: number) {
    console.log(`\n🔍 开始审查 PR #${prNumber}`)

    // 获取 PR 信息
    const { data: pr } = await this.octokit.pulls.get({
      owner,
      repo,
      pull_number: prNumber
    })

    // 获取改动的文件
    const { data: files } = await this.octokit.pulls.listFiles({
      owner,
      repo,
      pull_number: prNumber
    })

    let reviewComments: any[] = []

    // 对每个文件进行审查
    for (const file of files) {
      console.log(`\n📄 审查文件: ${file.filename}`)

      if (!this.shouldReviewFile(file.filename)) continue

      // 获取文件的 patch
      const patch = file.patch || ''

      // 使用 Code Review Skill 审查
      const review = await this.reviewSkill.execute({
        code: patch,
        context: 'Vue 3 + TypeScript + Tailwind CSS 项目',
        focusAreas: ['security', 'performance', 'maintainability']
      })

      // 转换为 GitHub comments
      reviewComments = reviewComments.concat(
        this.convertToGithubComments(review, file.filename)
      )
    }

    // 发布审查意见
    if (reviewComments.length > 0) {
      await this.publishReview(owner, repo, prNumber, reviewComments)
      console.log(`\n✅ 已发布 ${reviewComments.length} 条审查意见`)
    } else {
      console.log('\n✨ 代码审查通过！')
    }
  }

  private shouldReviewFile(filename: string): boolean {
    const extensions = ['.ts', '.tsx', '.vue', '.js', '.jsx']
    const excluded = ['node_modules', 'dist', 'build']
    return (
      extensions.some(ext => filename.endsWith(ext)) &&
      !excluded.some(dir => filename.includes(dir))
    )
  }

  private convertToGithubComments(review: any, filename: string) {
    // 将审查结果转换为 GitHub 评论格式
    return []
  }

  private async publishReview(
    owner: string,
    repo: string,
    prNumber: number,
    comments: any[]
  ) {
    // 发布到 GitHub PR
    await this.octokit.pulls.createReview({
      owner,
      repo,
      pull_number: prNumber,
      comments,
      event: 'COMMENT'
    })
  }
}

// 执行
const agent = new CodeReviewAgent()
const args = process.argv.slice(2)
const params = Object.fromEntries(args.map(arg => arg.split('=') as [string, string]))

agent.reviewPR(params.owner, params.repo, parseInt(params.pr))
```

