## Skill库设计详情

### Skill 1: Vue 组件生成 Skill（最高优先级）

#### 实现框架

```typescript
// skills/gen-vue-component.ts

import { Claude } from '@anthropic-ai/sdk'

interface VueComponentConfig {
  name: string                    // ComponentName
  type: 'form' | 'table' | 'card' | 'modal'
  fields?: Record<string, string> // 字段定义 {name: 'string', email: 'string'}
  styling: 'tailwind' | 'scss'
  features?: string[]             // 'validation' | 'loading' | 'error'
}

class GenVueComponentSkill {
  private claude = new Claude()

  async execute(config: VueComponentConfig): Promise<{
    component: string       // Vue 组件代码
    test: string           // 单元测试
    types: string          // TypeScript 类型定义
    doc: string            // 使用文档
  }> {
    // 第1步：生成 Vue 组件
    const componentPrompt = `
    生成一个 Vue 3 ${config.type} 组件，要求：

    组件名：${config.name}
    ${config.fields ? `字段：${JSON.stringify(config.fields)}` : ''}
    样式框架：${config.styling}
    额外功能：${config.features?.join(', ') || 'none'}

    要求：
    1. 使用 <script setup> 语法
    2. 完整的 TypeScript 类型定义
    3. 组件应该是可复用的
    4. 包含错误处理和 loading 态
    5. 包含详细的代码注释
    6. 遵循我们的代码规范：
       - 使用组合式API
       - 事件通过emit定义
       - Props通过defineProps定义

    输出格式：
    \`\`\`vue
    <template>
    ...
    </template>

    <script setup lang="ts">
    ...
    </script>

    <style scoped>
    ...
    </style>
    \`\`\`
    `

    const component = await this.claude.messages.create({
      model: 'claude-opus',
      max_tokens: 3000,
      messages: [{ role: 'user', content: componentPrompt }]
    })

    // 第2步：生成类型定义
    const typesPrompt = `
    基于刚才生成的Vue组件，生成对应的TypeScript类型定义。

    要求：
    1. export interface ${config.name}Props { ... }
    2. export interface ${config.name}Emits { ... }
    3. 所有可能的类型都要定义
    `

    const types = await this.claude.messages.create({
      model: 'claude-opus',
      max_tokens: 1000,
      messages: [
        { role: 'user', content: componentPrompt },
        { role: 'assistant', content: component.content[0].text },
        { role: 'user', content: typesPrompt }
      ]
    })

    // 第3步：生成单元测试
    const testPrompt = `
    为上面的Vue组件生成完整的单元测试（Vitest）。

    要求：
    1. 测试所有的prop组合
    2. 测试所有的emit事件
    3. 测试各种边界条件
    4. 使用 @vue/test-utils
    5. 使用 Mock 数据

    输出 TypeScript 测试代码：
    \`\`\`typescript
    import { describe, it, expect, vi } from 'vitest'
    import { mount } from '@vue/test-utils'
    ...
    \`\`\`
    `

    const test = await this.claude.messages.create({
      model: 'claude-opus',
      max_tokens: 2000,
      messages: [
        { role: 'user', content: componentPrompt },
        { role: 'assistant', content: component.content[0].text },
        { role: 'user', content: testPrompt }
      ]
    })

    // 第4步：生成使用文档
    const docPrompt = `
    为上面的Vue组件生成简明的使用文档，包括：
    1. 组件说明
    2. Props 列表及说明
    3. 事件列表及说明
    4. 使用示例（至少3个）
    5. 常见问题

    使用 Markdown 格式。
    `

    const doc = await this.claude.messages.create({
      model: 'claude-opus',
      max_tokens: 1500,
      messages: [
        { role: 'user', content: componentPrompt },
        { role: 'assistant', content: component.content[0].text },
        { role: 'user', content: docPrompt }
      ]
    })

    return {
      component: this.extractCode(component.content[0].text, 'vue'),
      types: this.extractCode(types.content[0].text, 'typescript'),
      test: this.extractCode(test.content[0].text, 'typescript'),
      doc: doc.content[0].text
    }
  }

  private extractCode(text: string, language: string): string {
    const regex = new RegExp(`\`\`\`${language}\n([\\s\\S]*?)\`\`\``)
    const match = text.match(regex)
    return match ? match[1] : text
  }
}

// 使用示例
const skill = new GenVueComponentSkill()
const result = await skill.execute({
  name: 'UserForm',
  type: 'form',
  fields: {
    name: 'string',
    email: 'string',
    phone: 'string',
    role: 'enum:admin|user|guest'
  },
  styling: 'tailwind',
  features: ['validation', 'loading']
})

console.log('✅ 组件生成完成')
console.log('📄 组件:', result.component)
console.log('🧪 测试:', result.test)
console.log('📚 文档:', result.doc)
```

