// skills/gen-unit-tests.ts

interface TestConfig {
  filePath: string              // 源文件路径
  testFramework: 'vitest' | 'jest'
  includeE2E?: boolean
  mockExternal?: boolean
}

class GenUnitTestsSkill {
  async execute(config: TestConfig) {
    // 读取源文件
    const sourceCode = await fs.readFile(config.filePath, 'utf-8')

    // 分析源代码的函数和逻辑
    const analysis = await this.analyzeCode(sourceCode)

    // 生成测试
