  ): Promise<void> {
    try {
      const message = this.formatMessage(report, config.format || 'json')

      await axios.post(config.webhookUrl, message, {
        headers: {
          'Content-Type': 'application/json'
        }
      })

      console.log(`✅ 已发送通知到自建机器人`)
